const snapshotStorageMigrationItems = `-- name: SnapshotStorageMigrationItems :execrows
INSERT INTO torrents.storage_migration_items (
    migration_id,
    object_id,
    source_location_id,
    destination_object_key,
    available_at,
    created_at,
    updated_at
)
SELECT
    $1::uuid,
    object.id,
    source.id,
    'torrents/sha256/' || substring(encode(object.content_sha256, 'hex') FROM 1 FOR 2)
        || '/' || encode(object.content_sha256, 'hex') || '.torrent',
    $2::timestamptz,
    $2::timestamptz,
    $2::timestamptz
FROM torrents.torrent_objects AS object
JOIN torrents.torrent_object_locations AS source
    ON source.object_id = object.id
   AND source.backend_id = $3::text
   AND source.state = 'verified'
   AND source.is_preferred = true
ORDER BY object.id
`

type SnapshotStorageMigrationItemsParams struct {
	MigrationID     uuid.UUID
	OccurredAt      pgtype.Timestamptz
	SourceBackendID string
}

func (q *Queries) SnapshotStorageMigrationItems(ctx context.Context, arg SnapshotStorageMigrationItemsParams) (int64, error) {
	result, err := q.db.Exec(ctx, snapshotStorageMigrationItems, arg.MigrationID, arg.OccurredAt, arg.SourceBackendID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
